Ltac r23_weq := apply bv_eq; lazymatch goal with |- ?g => tryif has_evar g then fail else (vm_compute; reflexivity) end.
(* [comment removed for export] *)
Ltac r23_eq := lazymatch goal with
  | |- ?a = ?b => tryif is_evar b then reflexivity else tryif is_evar a then reflexivity else r23_weq
  end.
(* [comment removed for export] *)
Ltac r23_side :=
  lazymatch goal with
  | |- MachineOk _ = MachineOk _ => f_equal; f_equal; try f_equal; try f_equal; try (unfold A_ATEXIT_STATICS, A_IN_CALLBACK23; r23_eq)
  | |- v_addi (getr _ _) _ = _ =>
      unfold A_ATEXIT_STATICS, A_IN_CALLBACK23;
      etransitivity; [ apply f_equal2; [ apply getr_same; gf_reg_neq | reflexivity ] | first [ r23_weq | reflexivity ] ]
  | |- rdn _ _ _ _ = _ => unfold A_IN_CALLBACK23 in *; assumption
  | |- ?g => fail 100 "r23_side: unexpected goal" g
  end.
