Ltac r23_jal_link F D :=
  unfold ax_foe_j1_stmt, ax_foe_j2_stmt, ax_foe_j3_stmt, ax_at_j1_stmt, ax_at_j2_stmt; intros fx regs mem rom;
  lazymatch type of F with fetch_word ?segs ?pc = Some ?w =>
    erewrite (step_jal_link segs regs pc mem rom w 1 _ F eq_refl D);
    cbn [bv_eqb Z.eqb]; r23_side
  end.
